OPENQASM 3.0;
    include "stdgates.inc";

    def my_function(readonly array[int[8], 2, 2] my_arr1, 
                    readonly array[int[8], 2, 2] my_arr2, 
                    qubit q) {
        for int[8] i in [0:1] {
            rx(my_arr1[i][0]) q;
            rx(my_arr2[i][1]) q;
        }

        return;
    }
    qubit my_q;
    array[int[8], 2, 2] arr_1 = { {1, 2}, {3, 4} };
    array[int[8], 2, 2] arr_2 = { {5, 6}, {7, 8} };
    my_function(arr_1, arr_2, my_q);
